/* ---------- přerušený běh vrátí zmutovaný soubor ----------
 * (nález T5 revize v22.9.9, 22. 9. 2026)
 *
 * V 19. testovacím kole se běh přerušil uprostřed mutace a v pracovní kopii
 * zůstal rozbitý serverový soubor (`if (false)` místo kontroly) — `finally`
 * ve smyčce se při ukončení signálem vůbec nespustí. Proto:
 *   – smyčka nečeká na sady synchronně (execFileSync blokoval smyčku událostí,
 *     takže by se obsluha signálu dostala ke slovu až po doběhnutí VŠECH
 *     mutací), sady běží přes execFile a na výsledek se čeká;
 *   – SIGINT (Ctrl+C), SIGTERM (kill, časový limit CI) i SIGHUP (zavřený
 *     terminál) nejdřív vrátí právě zmutovaný soubor, pak ukončí běžící sadu
 *     a skončí kódem 130;
 *   – totéž dělá pojistka při ukončení procesu (`exit`) — třeba po výjimce. */
let aktivni = null;        // { cesta, puvodni } — soubor, který je právě zmutovaný
let dite = null;           // právě běžící sada
function vratMutaci() {
  if (!aktivni) return null;
  const cesta = aktivni.cesta;
  writeFileSync(cesta, aktivni.puvodni, 'utf8');
  aktivni = null;
  return cesta;
}
for (const sig of ['SIGINT', 'SIGTERM', 'SIGHUP']) {
  process.on(sig, () => {
    let vraceno = null, chyba = null;
    try { vraceno = vratMutaci(); } catch (e) { chyba = e; }
    if (chyba) console.log('\nPŘERUŠENO (' + sig + ') — ZMUTOVANÝ SOUBOR SE NEPODAŘILO VRÁTIT: '
      + chyba.message + '\nVraťte ho ručně: git checkout -- netlify/ src/');
    else console.log('\nPŘERUŠENO (' + sig + ')'
      + (vraceno ? ' — zmutovaný soubor vrácen do původního znění: ' + vraceno : ' — žádný soubor nebyl zmutovaný') + '.');
    /* Běžící sadu ukončit a POČKAT na ni (nejvýš 2 s): proces, který skončí
     * dřív než jeho dítě, nechá po něm sirotka — v kontejneru bez init
     * procesu pak visí jako zombie. Soubor je v tu chvíli už vrácený. */
    if (!dite) process.exit(130);
    dite.once('exit', () => process.exit(130));
    try { dite.kill('SIGKILL'); } catch (e) { process.exit(130); }
    setTimeout(() => process.exit(130), 2000);
  });
}
process.on('exit', () => { try { vratMutaci(); } catch (e) { /* hlášeno výš */ } });

/* ---------- běh ---------- */
function spustSadu(sada) {
  return new Promise((hotovo) => {
    dite = execFile('node', [resolve(KOREN, sada)],
      { encoding: 'utf8', timeout: 120000, maxBuffer: 64 * 1024 * 1024,
        env: { ...process.env, NODE_PATH: process.env.NODE_PATH || '' } },
      (chyba, vystup) => { dite = null; hotovo({ chyba, vystup: String(vystup || '') }); });
  });
}

async function spustSady() {
  for (const sada of SADY) {
    const { chyba, vystup } = await spustSadu(sada);
    /* test_obnova.mjs píše souhrn „N OK, M FAIL", ostatní „prošlo/selhalo". */
    const m = /(\d+) (?:prošlo|OK), (\d+) (?:selhalo|FAIL)/.exec(vystup);
    if (m && Number(m[2]) > 0) return { chycena: true, kde: sada + ': ' + m[2] + ' selhalo', vystup };
    /* Pád sady je taky chycení — mutace rozbila kód tak, že se nedá ani
     * dojít na konec. Tichý průchod je jediná špatná odpověď. */
    if (chyba) return { chycena: true, kde: sada + ' (spadla)' };
    if (!m) return { chycena: true, kde: sada + ' (sada nedoběhla do souhrnu)' };
  }
  return { chycena: false };
}

const vybrane = MUTACE.filter(m => !filtr
  || m.nazev.toLowerCase().includes(filtr) || m.soubor.toLowerCase().includes(filtr));

/* RYCHLÁ KONTROLA ZADÁNÍ (`--kontrola`) — bez jediného spuštění sad.
 *
 * Proč vznikla (22. 9. 2026): dávka 4 změnila dva řádky, na které mířily
 * starší mutace, a jejich `hledej` se přestal nacházet. Plný běh to pozná
 * taky, jenže až po sedmnácti minutách a červeným CI — přitom je to chyba
 * v ZADÁNÍ mutace, ne v kódu. Tahle kontrola ji najde za vteřinu, takže se
 * dá pustit před commitem i jako samostatný krok v CI. */
if (process.argv.includes('--kontrola')) {
  const spatne = [];
  for (const m of MUTACE) {
    const cesta = resolve(KOREN, m.soubor);
    let obsah = '';
    try { obsah = readFileSync(cesta, 'utf8'); }
    catch (e) { spatne.push(m.nazev + ' — soubor ' + m.soubor + ' nejde přečíst'); continue; }
    const pocet = obsah.split(m.hledej).length - 1;
    if (pocet !== 1)
      spatne.push(m.nazev + ' — hledaný úsek v ' + m.soubor + ' nalezen ' + pocet + '×');
  }
  if (spatne.length) {
    console.log('CHYBNĚ ZADANÉ MUTACE (kód se změnil, mutace se nenašla):');
    spatne.forEach(s => console.log(' - ' + s));
    process.exit(1);
  }
  console.log('Zadání mutací je v pořádku: všech ' + MUTACE.length + ' úseků se v kódu našlo právě jednou.');
  process.exit(0);
}

/* ZÁMEK (B194, 19. 10. 2026): souběžný mutační běh nad toutéž pracovní
 * kopií shodí výchozí stav „bez mutace" (doloženo na test_vyjimky.mjs se
 * souběžnou mutací src/vyjimky.js) — nastroje/mutace_zamek.mjs. */
{ const { zamkniMutace, zamekHlaska } = await import('../nastroje/mutace_zamek.mjs');
  const drzi = zamkniMutace('netlify/mutace.mjs ' + process.argv.slice(2).join(' '));
  if (drzi) { console.log(zamekHlaska(drzi)); process.exit(2); } }

console.log('MUTAČNÍ TESTOVÁNÍ SERVEROVÉ VRSTVY');
console.log('Mutací k ověření: ' + vybrane.length + '   (sady: ' + SADY.join(', ') + ')\n');

/* Nejdřív se ověří, že je před zásahem všechno zelené — jinak by „chycená"
 * mutace znamenala jen to, že testy padaly už předtím. */
const vychozi = await spustSady();
if (vychozi.chycena) {
  console.log('PŘERUŠENO: sady nejsou zelené ani bez mutace — ' + vychozi.kde);
  /* B194: které kontroly spadly — bez toho se jednorázový pád výchozího
   * stavu (19. 10. 2026, test_vyjimky.mjs) nedal dohledat. */
  const padle = String(vychozi.vystup || '').split('\n').filter(r => /^\s*(FAIL|✗)/.test(r));
  if (padle.length) console.log(padle.slice(0, 20).map(r => '  ' + r.slice(0, 300)).join('\n'));
  process.exit(1);
}
console.log('Výchozí stav: obě sady zelené.\n');

let chycene = 0;
const nechycene = [];
const chybne = [];

for (const m of vybrane) {
  const cesta = resolve(KOREN, m.soubor);
  const puvodni = readFileSync(cesta, 'utf8');
  const pocet = puvodni.split(m.hledej).length - 1;
  if (pocet !== 1) {
    chybne.push(m.nazev + ' — hledaný úsek v ' + m.soubor + ' nalezen ' + pocet + '×');
    console.log('CHYBA ZADÁNÍ  ' + m.nazev + ' (úsek nalezen ' + pocet + '×)');
    continue;
  }
  try {
    aktivni = { cesta, puvodni };                // od téhle chvíle ho vrací i obsluha signálu
    writeFileSync(cesta, puvodni.replace(m.hledej, m.nahrad), 'utf8');
    const v = await spustSady();
    if (v.chycena) { chycene++; console.log('chycená      ' + m.nazev + '   → ' + v.kde); }
    else { nechycene.push(m); console.log('NECHYCENÁ    ' + m.nazev + '   → ' + m.proc); }
  } finally {
    vratMutaci();                                // vrátit vždy, i při pádu
  }
}

console.log('\n============================================================');
console.log('Chycených ' + chycene + ' z ' + (chycene + nechycene.length)
  + (chybne.length ? '   (chybně zadaných mutací: ' + chybne.length + ')' : ''));
if (nechycene.length) {
  console.log('\nNECHYCENÉ MUTACE — tohle by dnes testy nezachytily:');
  for (const m of nechycene) console.log(' - ' + m.nazev + ' (' + m.soubor + ')\n     ' + m.proc);
}
if (chybne.length) {
  console.log('\nCHYBNĚ ZADANÉ MUTACE (kód se změnil, mutace se nenašla):');
  for (const c of chybne) console.log(' - ' + c);
}
process.exitCode = (nechycene.length || chybne.length) ? 1 : 0;
